questionvariables.text:
/* Select a reference angle */
ref_index: rand(3);
ref_list: [30,45,60];
ref_angle: ref_list[ref_index+1];

/* Select the second, third or fourth quadrant (Quadrant IV added) */
quadrant: 2 + rand(3);
quadnames: ["I", "II", "III", "IV"];
quadname: quadnames[quadrant];

/* Construct the angle */
theta: if quadrant=2 then 180-ref_angle
       else if quadrant=3 then 180+ref_angle
       else 360-ref_angle;

/* Calculate exact trigonometric ratios */
sin_theta: sin(theta*%pi/180);
cos_theta: cos(theta*%pi/180);
/* Values for the reference angle (no signs), used in the worked solution and diagnostics */
sin_ref: sin(ref_angle*%pi/180);
cos_ref: cos(ref_angle*%pi/180);
sin_sign: if quadrant=2 then 1 else -1;
cos_sign: if quadrant=4 then 1 else -1;

/* Possible student mistakes */
sin_neg: -sin_theta;            /* right size, wrong sign */
cos_neg: -cos_theta;
sin_swap: cos_theta;            /* gave cos instead of sin */
cos_swap: sin_theta;
sin_mix: sin_sign*cos_ref;      /* right sign, sin and cos of the reference angle mixed up */
cos_mix: cos_sign*sin_ref;
